wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(41368676304103097248)
,p_plug_name=>'Product profitability report'
,p_static_id=>'product-profitability-report'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>10
,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    g.product_name,',
'    c.category_name AS category,',
'    s.supplier_name AS supplier,',
'    g.stock_qty,',
'    g.unit_cost,',
'    g.selling_price,',
'    (g.selling_price - g.unit_cost) AS profit_per_unit,',
'    (g.stock_qty * g.unit_cost) AS stock_value,',
'    (g.stock_qty * g.selling_price) AS potential_sales_value,',
'    (g.stock_qty * (g.selling_price - g.unit_cost)) AS potential_profit',
'FROM store_groceries g',
'JOIN store_categories c',
'    ON g.category_id = c.category_id',
'LEFT JOIN store_suppliers s',
'    ON g.supplier_id = s.supplier_id',
'WHERE g.status = ''ACTIVE''',
'ORDER BY potential_profit DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
